public class OpenedDomainFile<T> : AutoCloseable where T : DomainObject {
	public T content;

	public static OpenedDomainFile<T> open<T>/* where T : DomainObject */(Class<T> contentType,
			DomainFile file, bool okToUpgrade, bool okToRecover, TaskMonitor monitor)
    {
		return new(contentType, file, okToUpgrade, okToRecover, monitor);
	}

	public static OpenedDomainFile<T> open<T>/* where T : DomainObject */(Class<T> contentType,
			DomainFile file, TaskMonitor monitor)
    {
		return new(contentType, file, false, false, monitor);
	}

	public OpenedDomainFile(Class<T> contentType, DomainFile file, bool okToUpgrade,
			bool okToRecover, TaskMonitor monitor)
    {
		if (!contentType.isAssignableFrom(file.getDomainObjectClass())) {
			throw new ClassCastException("file " + file + " does not contain " + contentType +
				". got " + file.getDomainObjectClass() + " instead.");
		}
